import java.io.*;

public class Main {

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;

        int[] adj = new int[n];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int x = (int) in.nval - 1;
            in.nextToken();
            int y = (int) in.nval - 1;
            adj[x] |= 1 << y;
            adj[y] |= 1 << x;
        }

        int full = 1 << n;
        boolean[] ok = new boolean[full];
        ok[0] = true;
        long count = 1; // conjunto vazio (usado na DP, removido ao final)

        // mask e independente <=> remover o bit mais baixo ainda e independente,
        // e o vertice correspondente nao tem vizinhos dentro do mask
        for (int mask = 1; mask < full; mask++) {
            int v = Integer.numberOfTrailingZeros(mask);
            int rest = mask & (mask - 1);
            if (ok[rest] && (adj[v] & mask) == 0) {
                ok[mask] = true;
                count++;
            }
        }

        System.out.println(count - 1);
    }
}
